content.css:
/* ========================================================================== */
/* BFUSION Resource KPI — Modernised top-band cards + grey panel chrome      */
/* ========================================================================== */
.bfusion-root {
  width: 100%;
  height: 100%;
  overflow: auto;
  font-family: var(--rkpi-font-family, "Segoe UI"), wf_segoe-ui_normal, helvetica, arial, sans-serif;
  background-color: #FFFFFF;
  position: relative;
  color: #1F2937;
}
.bfusion-root *,
.bfusion-root *:before,
.bfusion-root *:after {
  box-sizing: border-box;
}
.bfusion-rkpi {
  display: flex;
  flex-direction: column;
  padding-bottom: 24px;
  /* license badge clear-zone */
}
/* ========================================================================== */
/* Header bar (title + subtitle + info button)                                */
/* ========================================================================== */
.rkpi-header {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 10px 18px 8px 18px;
  border-bottom: 1px solid #E5E7EB;
  background: #FFFFFF;
  position: relative;
}
.rkpi-header__titles {
  flex: 1 1 auto;
  min-width: 0;
}
.rkpi-header__title {
  font-weight: 700;
  color: #1F2937;
  letter-spacing: 0.1px;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: var(--rkpi-fs-header-title, 13px);
}
.rkpi-header__subtitle {
  margin-top: 2px;
  color: #6B7280;
  font-weight: 400;
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: var(--rkpi-fs-header-subtitle, 10px);
}
.rkpi-header__info {
  flex: 0 0 auto;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid #E5E7EB;
  background: #fff;
  color: #6B7280;
  font-style: italic;
  font-weight: 700;
  font-size: 11px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  line-height: 1;
  transition: all 0.15s ease;
}
.rkpi-header__info:hover {
  color: #fff;
  background: #E8612A;
  border-color: #E8612A;
  transform: scale(1.05);
}
.rkpi-header__info-pop {
  position: absolute;
  top: calc(100% + 6px);
  right: 12px;
  z-index: 30;
  width: 320px;
  max-width: calc(100% - 24px);
  background: #fff;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
  padding: 12px 14px;
  color: #1F2937;
  line-height: 1.45;
  font-size: var(--rkpi-fs-sub, 11px);
}
.rkpi-header__info-pop ul {
  margin: 8px 0 0 0;
  padding-left: 18px;
}
.rkpi-header__info-pop ul li {
  margin: 3px 0;
  color: #6B7280;
}
.rkpi-info-pop__title {
  font-weight: 700;
  color: #1F2937;
  margin-bottom: 4px;
}
.rkpi-info-pop__desc {
  color: #6B7280;
}
/* ========================================================================== */
/* Main wrapper                                                               */
/* ========================================================================== */
.rkpi-wrap {
  width: 100%;
  padding: 14px 18px 4px 18px;
  display: block;
  background: #FFFFFF;
}
.rkpi-row {
  margin-bottom: 14px;
}
.rkpi-row--r1,
.rkpi-row--r2 {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 10px;
}
/* ========================================================================== */
/* Modern KPI Card — top-band design                                          */
/* ========================================================================== */
.rkpi-card {
  --rkpi-card-color: #1F2A44;
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: box-shadow 0.2s ease, transform 0.15s ease;
  min-height: 122px;
}
.rkpi-card:hover {
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.08);
  transform: translateY(-1px);
}
.rkpi-card__band {
  background: var(--rkpi-card-color);
  color: #FFFFFF;
  padding: 8px 12px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  min-height: 30px;
}
.rkpi-card__band-title {
  font-size: var(--rkpi-fs-label, 11px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rkpi-card__band-meta {
  font-size: var(--rkpi-fs-band-meta, 10px);
  font-weight: 600;
  color: rgba(255, 255, 255, 0.85);
  white-space: nowrap;
}
.rkpi-card__body {
  padding: 12px 14px 12px 14px;
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
}
.rkpi-card__value {
  font-size: var(--rkpi-fs-value, 28px);
  font-weight: 700;
  line-height: 1.1;
  color: #1F2937;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.rkpi-card__unit {
  font-size: var(--rkpi-fs-unit, 11px);
  color: #6B7280;
  font-weight: 500;
  margin-left: 4px;
}
.rkpi-card__sub {
  font-size: var(--rkpi-fs-sub, 11px);
  color: #6B7280;
  line-height: 1.4;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rkpi-card__pbar {
  margin-top: auto;
  height: 4px;
  background: #F1F5F9;
  border-radius: 2px;
  overflow: hidden;
}
.rkpi-card__pbar-fill {
  height: 100%;
  border-radius: 2px;
  background: var(--rkpi-card-color);
  transition: width 0.3s ease;
}
/* ========================================================================== */
/* Section panel — grey header band + body                                    */
/* ========================================================================== */
.rkpi-panel {
  background: #FFFFFF;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  overflow: hidden;
  margin-bottom: 14px;
}
.rkpi-panel__head {
  background: linear-gradient(90deg, #F1F4F8 0%, #E9EEF4 100%);
  color: #1F2937;
  padding: 10px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid #E5E7EB;
}
.rkpi-panel__title {
  font-size: var(--rkpi-fs-panel-title, 12px);
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.8px;
  color: #1F2937;
}
.rkpi-panel__head-sub {
  font-size: var(--rkpi-fs-panel-sub, 11px);
  color: #6B7280;
  font-weight: 500;
  text-align: right;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 60%;
}
.rkpi-panel__body {
  padding: 14px 16px 16px 16px;
  background: #FFFFFF;
}
/* ========================================================================== */
/* Gauge Cards (Utilization | Bench Ratio) — inside .rkpi-panel               */
/* ========================================================================== */
.rkpi-gauges-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
.rkpi-gauge-card {
  background: #F8FAFC;
  border: 1px solid #E5E7EB;
  border-radius: 8px;
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  min-width: 0;
  transition: box-shadow 0.15s ease, transform 0.15s ease;
}
.rkpi-gauge-card:hover {
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
  transform: translateY(-1px);
}
.rkpi-gauge__title {
  font-size: var(--rkpi-fs-gauge-title, 11px);
  color: #6B7280;
  font-weight: 700;
  letter-spacing: 0.8px;
  text-transform: uppercase;
  margin-bottom: 6px;
}
.rkpi-gauge__body {
  display: flex;
  align-items: stretch;
  gap: 12px;
  min-width: 0;
}
.rkpi-gauge__left {
  flex: 0 0 150px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  min-width: 0;
}
.rkpi-gauge__value {
  font-size: var(--rkpi-fs-gauge-value, 22px);
  font-weight: 700;
  line-height: 1.1;
  margin-bottom: 2px;
  font-variant-numeric: tabular-nums;
}
.rkpi-gauge__svg {
  width: 150px;
  max-width: 100%;
  height: auto;
}
.rkpi-gauge__right {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 0;
  min-width: 0;
}
.rkpi-gauge__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 6px 4px;
  font-size: var(--rkpi-fs-gauge-row, 11px);
  border-top: 1px solid #E5E7EB;
}
.rkpi-gauge__row:first-child {
  border-top: none;
}
.rkpi-gauge__row-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: #6B7280;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.rkpi-gauge__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  flex-shrink: 0;
  display: inline-block;
}
.rkpi-gauge__row-value {
  font-weight: 700;
  text-align: right;
  white-space: nowrap;
  flex-shrink: 0;
  font-variant-numeric: tabular-nums;
}
.rkpi-gauge__badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 0.85em;
  font-weight: 700;
  letter-spacing: 0.5px;
  color: #fff !important;
}
/* ========================================================================== */
/* Allocation Distribution — inside .rkpi-panel                               */
/* ========================================================================== */
.rkpi-distrib {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.rkpi-distrib__subtitle {
  font-size: var(--rkpi-fs-distrib-sub, 11px);
  color: #6B7280;
  margin-bottom: 2px;
}
.rkpi-distrib__bar {
  width: 100%;
  height: 22px;
  background: #F1F5F9;
  border-radius: 6px;
  overflow: hidden;
  display: flex;
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.02);
}
.rkpi-distrib__seg {
  height: 100%;
  transition: width 0.3s ease;
}
.rkpi-distrib__seg:hover {
  opacity: 0.85;
}
.rkpi-distrib__legend {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}
.rkpi-legend {
  font-size: var(--rkpi-fs-distrib-sub, 11px);
  color: #1F2937;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-weight: 500;
}
.rkpi-legend strong {
  font-weight: 700;
  color: #1F2937;
  font-variant-numeric: tabular-nums;
}
.rkpi-legend__dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  display: inline-block;
  flex-shrink: 0;
}
/* ========================================================================== */
/* Insight panel — rows inside .rkpi-panel                                    */
/* ========================================================================== */
.rkpi-insight {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.rkpi-insight__row {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 6px;
  border: 1px solid #E5E7EB;
}
.rkpi-insight__icon {
  font-size: 20px;
  flex-shrink: 0;
  line-height: 1;
}
.rkpi-insight__text {
  flex: 1;
  min-width: 0;
}
.rkpi-insight__headline {
  font-size: var(--rkpi-fs-insight-headline, 11px);
  font-weight: 700;
  line-height: 1.3;
}
.rkpi-insight__detail {
  font-size: var(--rkpi-fs-insight-detail, 10px);
  color: #6B7280;
  line-height: 1.3;
  margin-top: 2px;
}
/* Distribution + Insights side-by-side at wide widths */
.rkpi-row--insights-grid {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 14px;
  margin-bottom: 14px;
}
/* ========================================================================== */
/* Responsive                                                                 */
/* ========================================================================== */
.bfusion-rkpi.rkpi-narrow .rkpi-row--insights-grid {
  grid-template-columns: 1fr;
}
.bfusion-rkpi.rkpi-narrow .rkpi-gauges-grid {
  grid-template-columns: 1fr;
}
.bfusion-rkpi.rkpi-medium .rkpi-row--insights-grid {
  grid-template-columns: 1fr;
}
/* ========================================================================== */
/* Landing Page (shared pattern)                                              */
/* ========================================================================== */
.bfusion-landing-wrap {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  background-color: #FFFFFF;
}
.bfusion-landing {
  display: flex;
  flex-direction: column;
  align-items: center;
  max-width: 420px;
  padding: 20px;
  box-sizing: border-box;
  text-align: center;
}
.bfusion-landing__logo-container {
  width: 130px;
  height: 84px;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: #E8612A;
  border-radius: 12px;
  box-shadow: 0 3px 8px rgba(0, 0, 0, 0.08);
  margin-bottom: 24px;
  overflow: hidden;
}
.bfusion-landing__logo {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.bfusion-landing__text-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 100%;
}
.bfusion-landing__title {
  font-size: 15px;
  font-weight: 600;
  color: #242424;
  margin: 0 0 14px 0;
  padding: 0;
  line-height: 1.2;
}
.bfusion-landing__description {
  font-size: 11.5px;
  font-weight: 400;
  color: #666666;
  margin: 0;
  padding: 0;
  line-height: 1.5;
}
.bfusion-landing__description strong {
  font-weight: 600;
  color: #444444;
}
.bfusion-landing__separator {
  width: 60%;
  height: 1px;
  background-color: #EAEAEA;
  margin: 20px 0;
}
.bfusion-landing__metadata {
  font-size: 10.5px;
  color: #8C8C8C;
  margin-bottom: 4px;
  font-weight: 400;
  line-height: 1.4;
}
.bfusion-landing__metadata strong {
  font-weight: 600;
  color: #707070;
}
/* ========================================================================== */
/* License Badge & Watermark                                                  */
/* ========================================================================== */
.bfusion-license-badge-wrap {
  position: absolute;
  bottom: 4px;
  left: 8px;
  z-index: 20;
  pointer-events: none;
}
.bfusion-license-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 4px;
  font-size: 9px;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  line-height: 1.3;
  pointer-events: auto;
  max-width: 380px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge--valid {
  background: rgba(5, 150, 105, 0.08);
  border: 1px solid rgba(5, 150, 105, 0.25);
  color: #059669;
}
.bfusion-license-badge--invalid {
  background: rgba(220, 38, 38, 0.06);
  border: 1px solid rgba(220, 38, 38, 0.2);
  color: #DC2626;
}
.bfusion-license-badge__icon {
  font-size: 11px;
  flex-shrink: 0;
}
.bfusion-license-badge__text {
  overflow: hidden;
  text-overflow: ellipsis;
}
.bfusion-license-badge__text strong {
  font-weight: 600;
}
.bfusion-watermark {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 15;
  pointer-events: none;
  display: flex;
  align-items: center;
  justify-content: center;
  background: repeating-linear-gradient(-45deg, transparent, transparent 120px, rgba(220, 38, 38, 0.03) 120px, rgba(220, 38, 38, 0.03) 122px);
}
.bfusion-watermark__content {
  text-align: center;
  opacity: 0.18;
  user-select: none;
  transform: rotate(-18deg);
}
.bfusion-watermark__title {
  font-size: 56px;
  font-weight: 900;
  color: #DC2626;
  letter-spacing: 12px;
  line-height: 1;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__subtitle {
  font-size: 16px;
  font-weight: 600;
  color: #DC2626;
  margin-top: 6px;
  letter-spacing: 3px;
  text-transform: uppercase;
  font-family: "Segoe UI", sans-serif;
}
.bfusion-watermark__link {
  font-size: 11px;
  color: #9CA3AF;
  margin-top: 12px;
  font-family: "Segoe UI", sans-serif;
}
/* ========================================================================== */
/* Empty Data State                                                           */
/* ========================================================================== */
.bfusion-empty {
  display: flex;
  width: 100%;
  height: 100%;
  align-items: center;
  justify-content: center;
  padding: 20px 24px 28px 24px;
  box-sizing: border-box;
}
.bfusion-empty__message {
  font-size: 12px;
  color: #94a3b8;
  font-weight: 400;
  text-align: center;
  letter-spacing: 0.2px;
}
